import React, { useState, useEffect, useRef } from 'react';
import { Bot, X, Send, Mic, MessageSquare, MicOff } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import './ChatBot.css';

const N8N_WEBHOOK_URL = 'https://20.17.177.221.nip.io/webhook-test/employee-assistant';
const TEMP_JWT_TOKEN  = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiJ1c2VyMTIzIiwidXBuIjoicGVrZXJqYUBjaGluaGluLmNvbSIsInJvbGVzIjpbImVtcGxveWVlIl0sInRlbmFudF9pZCI6ImNoaW5oaW5faHEifQ.UqTWTIrSmD9WwDQQd93W17xFMkAqHeZJf2mSg08ldKU';
const ELEVATED_PATHS  = ['/dashboard', '/info'];

const ChatBot = () => {
  const location = useLocation();
  const [isOpen,   setIsOpen]   = useState(false);
  const [mode,     setMode]     = useState('text'); // 'text' | 'voice'
  const [messages, setMessages] = useState([
    { id: 1, sender: 'bot', msgType: 'text', text: 'Hi! I am your Employee Assistant. Type a message or switch to Voice Mode to talk to me.' }
  ]);
  const [inputValue,        setInputValue]        = useState('');
  const [isRecording,       setIsRecording]       = useState(false);
  const [voiceTranscript,   setVoiceTranscript]   = useState('');
  const [isLoading,         setIsLoading]         = useState(false);
  const [conversationState, setConversationState] = useState({});
  const messagesEndRef = useRef(null);
  const recognitionRef = useRef(null);
  const isElevated     = ELEVATED_PATHS.includes(location.pathname);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isOpen]);

  useEffect(() => {
    return () => { recognitionRef.current?.abort(); };
  }, []);

  const speakText = (text) => {
    if (!('speechSynthesis' in window)) return;
    window.speechSynthesis.cancel();
    const u = new SpeechSynthesisUtterance(text);
    u.lang = 'en-US';
    window.speechSynthesis.speak(u);
  };

  const addAiMessage = (text, msgType = 'text') =>
    setMessages(prev => [...prev, { id: Date.now(), sender: 'bot', msgType, text }]);

  const handleSendMessage = async (text, inputType = 'text', confirmData = null) => {
    if (!text && !confirmData) return;
    if (!confirmData) {
      setMessages(prev => [...prev, { id: Date.now(), sender: 'user', msgType: 'text', text }]);
      setInputValue('');
      setVoiceTranscript('');
    }
    setIsLoading(true);
    const payload = confirmData
      ? { text: 'User confirmed the plan', input_type: inputType, state: conversationState, confirm: true, edited_plan: confirmData.plan, client_request_id: `req-${Date.now()}` }
      : { text, input_type: inputType, state: conversationState, client_request_id: `req-${Date.now()}` };
    try {
      const res = await fetch(N8N_WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${TEMP_JWT_TOKEN}` },
        body: JSON.stringify(payload),
      });
      processN8nResponse(await res.json(), inputType);
    } catch {
      addAiMessage('System offline. Cannot connect to the assistant.');
    } finally {
      setIsLoading(false);
    }
  };

  const processN8nResponse = (data, inputType) => {
    let textToSpeak = '';
    if (data.state) setConversationState(data.state);
    switch (data.type) {
      case 'clarify':
        textToSpeak = data.question; addAiMessage(data.question); break;
      case 'confirm':
        textToSpeak = data.summary + '. Do you want to proceed?';
        setMessages(prev => [...prev, { id: Date.now(), sender: 'bot', msgType: 'confirm_card', text: data.summary, plan: data.plan, confirm_token: data.confirm_token }]);
        break;
      case 'receipt':
        textToSpeak = 'Success! ' + data.summary; addAiMessage(textToSpeak); setConversationState({}); break;
      case 'error':
      case 'auth_error':
        textToSpeak = 'Sorry, ' + (data.message || data.error); addAiMessage(textToSpeak); break;
      default:
        addAiMessage("I received a response, but I'm not sure how to display it.");
    }
    if (inputType === 'voice' && textToSpeak) speakText(textToSpeak);
  };

  const startRecording = () => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Your browser does not support voice. Please use Google Chrome.'); return; }
    const rec = new SR();
    rec.lang           = 'en-US';
    rec.interimResults = true;
    rec.continuous     = false;
    rec.onstart  = () => { setIsRecording(true); setVoiceTranscript(''); window.speechSynthesis.cancel(); };
    rec.onresult = (e) => {
      let interim = '', final = '';
      for (let i = e.resultIndex; i < e.results.length; i++) {
        if (e.results[i].isFinal) final += e.results[i][0].transcript;
        else interim += e.results[i][0].transcript;
      }
      setVoiceTranscript(final || interim);
      if (final) handleSendMessage(final.trim(), 'voice');
    };
    rec.onerror = () => { setIsRecording(false); setVoiceTranscript(''); };
    rec.onend   = () => setIsRecording(false);
    recognitionRef.current = rec;
    rec.start();
  };

  const stopRecording = () => {
    recognitionRef.current?.stop();
    setIsRecording(false);
  };

  const switchMode = (newMode) => {
    stopRecording();
    setVoiceTranscript('');
    setMode(newMode);
  };

  return (
    <>
      {/* FAB */}
      <div
        className={`chatbot-static-fab ${isOpen ? 'chatbot-fab-open' : ''} ${isElevated ? 'chatbot-fab-elevated' : ''}`}
        onClick={() => setIsOpen(o => !o)}
        title="Employee Assistant"
      >
        <div className="chatbot-fab-ring" />
        {isOpen ? <X size={26} color="white" /> : <Bot size={26} color="white" />}
        {!isOpen && <span className="chatbot-fab-badge">AI</span>}
      </div>

      {/* Backdrop */}
      {isOpen && <div className="chat-backdrop" onClick={() => setIsOpen(false)} />}

      {/* Chat Window */}
      {isOpen && (
        <div
          className="chat-window-overlay"
          onClick={e => e.stopPropagation()}
          onMouseDown={e => e.stopPropagation()}
          onTouchStart={e => e.stopPropagation()}
        >
          {/* Header */}
          <div className="chat-header">
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <div style={{ width: 32, height: 32, borderRadius: '50%', background: 'rgba(255,255,255,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                <Bot size={18} color="white" />
              </div>
              <div>
                <div style={{ fontWeight: 700, fontSize: 14 }}>Smart Assistant</div>
                <div style={{ fontSize: 10, opacity: 0.7 }}>● Online</div>
              </div>
            </div>
            <X size={20} onClick={() => setIsOpen(false)} style={{ cursor: 'pointer', opacity: 0.8 }} />
          </div>

          {/* Mode Toggle */}
          <div className="chat-mode-toggle">
            <button className={`chat-mode-btn ${mode === 'text' ? 'active' : ''}`} onClick={() => switchMode('text')}>
              <MessageSquare size={14} /> Text
            </button>
            <button className={`chat-mode-btn ${mode === 'voice' ? 'active' : ''}`} onClick={() => switchMode('voice')}>
              <Mic size={14} /> Voice
            </button>
          </div>

          {/* Messages */}
          <div className="chat-messages">
            {messages.map(m => (
              <div key={m.id} className={`message ${m.sender}`}>
                <p style={{ margin: 0 }}>{m.text}</p>
                {m.msgType === 'confirm_card' && (
                  <div style={{ marginTop: 10, display: 'flex', gap: 8 }}>
                    <button style={{ padding: '6px 10px', background: '#28a745', color: 'white', border: 'none', borderRadius: 6, cursor: 'pointer', fontSize: 12, flex: 1 }}
                      onClick={() => handleSendMessage(null, 'text', m)}>Confirm</button>
                    <button style={{ padding: '6px 10px', background: '#dc3545', color: 'white', border: 'none', borderRadius: 6, cursor: 'pointer', fontSize: 12, flex: 1 }}
                      onClick={() => addAiMessage('Action cancelled.')}>Cancel</button>
                  </div>
                )}
              </div>
            ))}
            {isLoading && (
              <div className="message bot" style={{ opacity: 0.7 }}>
                <span className="chatbot-typing-dots"><span /><span /><span /></span>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* TEXT MODE */}
          {mode === 'text' && (
            <div className="chat-input-area">
              <input
                value={inputValue}
                onChange={e => setInputValue(e.target.value)}
                placeholder="Type your message..."
                onKeyPress={e => e.key === 'Enter' && handleSendMessage(inputValue, 'text')}
                disabled={isLoading}
                style={{ pointerEvents: 'all', position: 'relative', zIndex: 10002 }}
              />
              <button
                className="send-btn"
                onClick={() => handleSendMessage(inputValue, 'text')}
                disabled={!inputValue.trim() || isLoading}
                style={{ opacity: (!inputValue.trim() || isLoading) ? 0.4 : 1 }}
              >
                <Send size={18} />
              </button>
            </div>
          )}

          {/* VOICE MODE */}
          {mode === 'voice' && (
            <div className="chat-voice-panel">
              <div className="voice-transcript-box">
                {voiceTranscript
                  ? <span className="voice-transcript-text">{voiceTranscript}</span>
                  : <span className="voice-transcript-hint">
                      {isRecording ? 'Listening…' : 'Tap the mic and speak'}
                    </span>
                }
              </div>

              <button
                className={`voice-mic-btn ${isRecording ? 'recording' : ''}`}
                onClick={isRecording ? stopRecording : startRecording}
                disabled={isLoading}
              >
                {isRecording && <><div className="voice-mic-ripple" /><div className="voice-mic-ripple delay" /></>}
                {isRecording ? <MicOff size={32} color="white" /> : <Mic size={32} color="white" />}
              </button>

              <p className="voice-mic-hint">
                {isLoading ? 'Processing…' : isRecording ? 'Tap to stop' : 'Tap to speak'}
              </p>
            </div>
          )}
        </div>
      )}

    </>
  );
};

export default ChatBot;
